param([string]$Root = (Join-Path ${env:ProgramFiles} 'ContentOps\Client'),[string]$DataRoot = (Join-Path $env:ProgramData 'ContentOps\Client'),[int]$MaxCycles=0)
$delay=3;$cycles=0; while(($MaxCycles -eq 0) -or ($cycles -lt $MaxCycles)){$cycles++; foreach($name in 'yt_notifi','ytdownload'){$port=if($name -eq 'yt_notifi'){8787}else{8790}; try{Invoke-RestMethod "http://127.0.0.1:$port/health" -TimeoutSec 3|Out-Null}catch{& (Join-Path $PSScriptRoot 'Start-ContentOpsClient.ps1') -Root $Root -DataRoot $DataRoot; Start-Sleep $delay; $delay=[Math]::Min($delay*2,60)}}; Start-Sleep 5}
